function fewestDistinct(nums: number[], k: number): number {
  const counts = [...nums.reduce((m, x) => m.set(x, (m.get(x) ?? 0) + 1), new Map<number, number>()).values()];
  const d = counts.length;
  let best = 0;
  for (let mask = 0; mask < 1 << d; mask++) {
    let cost = 0, gone = 0;
    for (let i = 0; i < d; i++) if (mask & (1 << i)) { cost += counts[i]; gone++; }
    if (cost <= k) best = Math.max(best, gone);
  }
  return d - best;
}

