class Solution:
    def fewestDistinct(self, nums: List[int], k: int) -> int:
        counts = list(Counter(nums).values())
        d = len(counts)
        best = 0
        for mask in range(1 << d):
            chosen = [counts[i] for i in range(d) if mask >> i & 1]
            if sum(chosen) <= k:
                best = max(best, len(chosen))
        return d - best

