function fewestDistinct(nums: number[], k: number): number {
  const freq = new Map<number, number>();
  for (const x of nums) freq.set(x, (freq.get(x) ?? 0) + 1);
  const howMany = new Array(nums.length + 1).fill(0); // howMany[c] = values with count c
  for (const c of freq.values()) howMany[c]++;
  let left = freq.size;
  for (let c = 1; c <= nums.length && k >= c; c++) {
    const take = Math.min(howMany[c], Math.floor(k / c));
    k -= take * c;
    left -= take;
    if (take < howMany[c]) break;
  }
  return left;
}

